var MONTHS = {JAN:1,FEB:2,MAR:3,APR:4,MAY:5,JUN:6,JUL:7,AUG:8,SEP:9,OCT:10,NOV:11,DEC:12};
var DOWS = {SUN:0,MON:1,TUE:2,WED:3,THU:4,FRI:5,SAT:6};
var DOWCN = ['周日','周一','周二','周三','周四','周五','周六'];
var MONTHCN = ['','1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
function pad(n){ return (n<10?'0':'')+n; }
function parseField(field, min, max, names){
  var allowed = {};
  var parts = String(field).toUpperCase().split(',');
  function mapName(tok){
    tok = tok.trim();
    if(names && names[tok] !== undefined) return names[tok];
    var n = parseInt(tok,10);
    if(n === 7) return 0;
    return n;
  }
  for(var i=0;i<parts.length;i++){
    var p = parts[i].trim();
    if(p === '') continue;
    var step = 1, range;
    var slash = p.indexOf('/');
    if(slash >= 0){ step = parseInt(p.slice(slash+1),10); range = p.slice(0,slash); }
    else range = p;
    var lo, hi;
    if(range === '*' || range === ''){ lo = min; hi = max; }
    else {
      var dash = range.indexOf('-');
      if(dash >= 0){ lo = mapName(range.slice(0,dash)); hi = mapName(range.slice(dash+1)); }
      else { lo = mapName(range); hi = lo; }
    }
    if(isNaN(lo) || isNaN(hi) || isNaN(step)) return null;
    for(var v = lo; v <= hi; v += step){ allowed[v] = true; }
  }
  return allowed;
}
function parse(expr){
  var f = String(expr).trim().split(/\s+/);
  if(f.length !== 5) return null;
  var min = parseField(f[0],0,59,null);
  var hour = parseField(f[1],0,23,null);
  var dom = parseField(f[2],1,31,null);
  var mon = parseField(f[3],1,12,MONTHS);
  var dow = parseField(f[4],0,6,DOWS);
  if(!min || !hour || !dom || !mon || !dow) return null;
  return {min:min,hour:hour,dom:dom,mon:mon,dow:dow,raw:f};
}
function fits(parsed, d){
  if(!parsed.min[d.getMinutes()]) return false;
  if(!parsed.hour[d.getHours()]) return false;
  if(!parsed.mon[d.getMonth()+1]) return false;
  var domStar = parsed.raw[2] === '*';
  var dowStar = parsed.raw[4] === '*';
  var domOk = !!parsed.dom[d.getDate()];
  var dowOk = !!parsed.dow[d.getDay()];
  if(!domStar && !dowStar) return domOk || dowOk;
  if(!domStar) return domOk;
  if(!dowStar) return dowOk;
  return true;
}
function next(expr, from, limit){
  var p = parse(expr); if(!p) return null;
  limit = limit || (8*366*24*60);
  var d = from ? new Date(from.getTime()) : new Date();
  d.setSeconds(0,0); d.setMinutes(d.getMinutes()+1);
  for(var i=0;i<limit;i++){
    if(fits(p,d)) return new Date(d.getTime());
    d.setMinutes(d.getMinutes()+1);
  }
  return null;
}
function nextN(expr, from, n){
  var out = []; var cur = from ? new Date(from.getTime()) : new Date();
  for(var k=0;k<n;k++){
    var r = next(expr, cur); if(!r) break;
    out.push(new Date(r.getTime()));
    cur = new Date(r.getTime()); cur.setMinutes(cur.getMinutes()+1);
  }
  return out;
}
function stepOf(arr, max){ if(arr.length<2) return 0; var k=arr[1]-arr[0]; if(k<=0||arr[0]!==0) return 0; for(var i=1;i<arr.length;i++) if(arr[i]!==arr[i-1]+k) return 0; if((arr.length-1)*k>max) return 0; return k; }
function describe(expr){
  var p = parse(expr); if(!p) return '表达式无法解析';
  if((expr||'').trim() === '* * * * *') return '每分钟';
  var allMin = Object.keys(p.min).length === 60;
  var allHour = Object.keys(p.hour).length === 24;
  var domStar = p.raw[2] === '*', monStar = p.raw[3] === '*', dowStar = p.raw[4] === '*';
  var mins = Object.keys(p.min).map(Number).sort(function(a,b){return a-b;});
  var hours = Object.keys(p.hour).map(Number).sort(function(a,b){return a-b;});
  var mk = stepOf(mins, 59);
  var t = '';
  if(mins.length === 1 && hours.length === 1) t = pad(hours[0]) + ':' + pad(mins[0]);
  else if(mk > 0) t = '每 ' + mk + ' 分钟';
  else if(mins.length === 1 && allHour) t = '每小时第 ' + pad(mins[0]) + ' 分钟';
  else if(allMin && hours.length === 1) t = '每小时 ' + pad(hours[0]) + ' 分';
  else if(allMin && allHour) t = '每分钟';
  else {
    var hs = allHour ? '每小时' : ('在 ' + hours.map(pad).join('/') + ' 点');
    var ms = allMin ? '' : (' 的 ' + mins.map(pad).join('/') + ' 分');
    t = hs + ms;
  }
  var when = [];
  if(!domStar || !dowStar){
    if(!dowStar){
      var dw = Object.keys(p.dow).map(Number).sort(function(a,b){return a-b;}).map(function(x){return DOWCN[x];});
      when.push('每周' + dw.join('、'));
    }
    if(!domStar){
      var dm = Object.keys(p.dom).map(Number).sort(function(a,b){return a-b;});
      when.push('每月 ' + dm.join('、') + ' 日');
    }
  }
  if(!monStar){
    var mn = Object.keys(p.mon).map(Number).sort(function(a,b){return a-b;}).map(function(x){return MONTHCN[x];});
    when.push('每年 ' + mn.join('、') + ' 月');
  }
  var s = '';
  if(domStar && monStar && dowStar && t !== '每分钟') s = '每天 ';
  if(when.length) s += when.join(' ') + ' ';
  s += t;
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parse:parse, fits:fits, next:next, nextN:nextN, describe:describe, parseField:parseField };
}
if (typeof window !== 'undefined') {
  window.CronForgePure = { parse:parse, fits:fits, next:next, nextN:nextN, describe:describe };
}
